/** LOTEDIARIO: primer step. P100 entrega fechas codificadas en TASKVALUE (aaaammddxx). */
@Component
@RequiredArgsConstructor
public class FechasLoteTasklet implements Tasklet {

    private final CalendarioLoteService p100;      // S500P100 con PARAM100 = 9, 2, 6, 7, 1

    @Override
    public RepeatStatus execute(StepContribution sc, ChunkContext cc) {
        FechaLote f = p100.fechaLoteYNodo();       // PARAM100 = "1"
        var ctx = cc.getStepContext().getStepExecution().getJobExecution().getExecutionContext();
        ctx.put("idTeleton",        p100.idTeleton());        // "9"
        ctx.put("fechaAyer",        p100.fechaAyer());        // "2"
        ctx.put("fechaUltDiaMes",   p100.ultimoDiaMes());     // "6"
        ctx.put("fechaPrimDiaMes",  p100.primerDiaMes());     // "7"
        ctx.put("fechaBatch",       f.fecha());               // T100(VALUE) / 100
        ctx.put("nodoSistema",      f.nodo());                // T100(VALUE) MOD 100
        ctx.put("calendario",       Calendario.de(f.fecha())); // FECHAS(FECHAMAQ): DIAFINSEM, DIA30...
        return RepeatStatus.FINISHED;
    }
}
