/** Equivalente a VALIARCHCTRL cuando se migre por fases y convivan WFL y Spring Batch. */
@Repository
@RequiredArgsConstructor
public class ControlPasoRepository {

    private final JdbcTemplate jdbc;

    public boolean terminado(LocalDate fechaBatch, int nodo, String clavePaso) {
        return jdbc.queryForObject("""
                select count(*) from ctrl_wfl_lote
                 where fecha_batch = ? and nodo = ? and clave_paso = ?
                """, Integer.class, fechaBatch, nodo, clavePaso) > 0;
    }
}

