@Bean
Flow inicioLote(Step resta24h, Step s151p177Linea, Step p165PagosPend, Step p103Archivo) {
    // PROCESS ... [Txxx] lanza en paralelo; el WAIT(Txxx) posterior es el join del split.
    return new FlowBuilder<SimpleFlow>("inicioLote")
            .split(loteTaskExecutor)
            .add(flow(resta24h),          // S500P005REST24H  - P005(5)
                 flow(s151p177Linea),     // S151P177MVLINEA
                 flow(p165PagosPend),     // S500P165PAGPEND  - se espera en WAIT(TA165)
                 flow(p103Archivo))       // S500P103ARCHIVO
            .build();
}

@Bean
TaskExecutor loteTaskExecutor() {
    var ex = new ThreadPoolTaskExecutor();
    ex.setCorePoolSize(8);                // el WFL no limita; definir con operación
    ex.setThreadNamePrefix("lote-");
    return ex;
}

/** RS500P130: corte de comisiones con tres instancias concurrentes de P130. */
@Bean
Step p130CorteComisiones(JobRepository repo, Step p130Particion, P130Partitioner particiones) {
    return new StepBuilder("S500P130CORTCOM", repo)
            .partitioner("p130", particiones)     // ORIGINAL, COPIA y COPIA3
            .step(p130Particion)
            .gridSize(3)
            .taskExecutor(loteTaskExecutor)
            .build();
}

@Component
public class P130Partitioner implements Partitioner {
    @Override
    public Map<String, ExecutionContext> partition(int grid) {
        return Map.of("original", ctx(1), "copia", ctx(2), "copia3", ctx(3));
    }
}

