// SYSTEM/FORZA("S500/LIST/P130") se vuelve un StepExecutionListener que publica el listado.

/** IF DIAFINSEM OR DIA30 / IF ESPRODUCCION OR ESPBAACEPT. */
@Component
public class CalendarioDecider implements JobExecutionDecider {
    @Override
    public FlowExecutionStatus decide(JobExecution job, StepExecution last) {
        Calendario c = (Calendario) job.getExecutionContext().get("calendario");
        return (c.diaFinSemana() || c.dia30())
                ? new FlowExecutionStatus("TESORERIA")
                : new FlowExecutionStatus("CONTINUA");
    }
}

@Bean
Flow tesoreria(Step p187, Step p200Tesoreria, Step envioRendTesoreria, AmbienteProps amb) {
    var f = new FlowBuilder<SimpleFlow>("tesoreria").start(p200Tesoreria);
    if (amb.envioTesoreriaHabilitado()) {       // ESPRODUCCION OR ESPBAACEPT
        f.next(envioRendTesoreria);             // S500ENVRENTESOR
    }
    return new FlowBuilder<SimpleFlow>("p187YTesoreria")
            .start(p187)                        // S500P187EJEP188
            .next(calendarioDecider).on("TESORERIA").to(f.build())
            .from(calendarioDecider).on("CONTINUA").end()
            .build();
}

/** FALLA: el WFL se detiene en consola (ACCEPT) hasta que el operador decide. */
public enum DecisionOperador { REINTENTAR, CONTINUAR, TERMINAR, CAMBIAR_VERSION }

@Component
@RequiredArgsConstructor
public class FallaPasoHandler implements StepExecutionListener {

    private final OperacionConsola consola;     // pantalla de operación / ticket con respuesta

    @Override
    public ExitStatus afterStep(StepExecution step) {
        if (step.getStatus() != BatchStatus.FAILED) return step.getExitStatus();

        boolean soloContinuar = step.getStepName().equals("S500P101")
                && (fallasP130(step) > 0 || idFallaPaso(step) > 0);   // FALLAC1..3, IDFALLAPASO
        Set<DecisionOperador> opciones = soloContinuar
                ? EnumSet.of(CONTINUAR)
                : EnumSet.allOf(DecisionOperador.class);

        return switch (consola.espera(step, opciones)) {     // DO ACCEPT ... UNTIL
            case CONTINUAR       -> ExitStatus.COMPLETED.addExitDescription("continuado por operador");
            case TERMINAR        -> ExitStatus.FAILED;                   // GO FIN
            case REINTENTAR      -> new ExitStatus("REINTENTAR");        // transición al mismo step
            case CAMBIAR_VERSION -> new ExitStatus("CAMBIAR_VERSION");   // S006/WFL/CAMBIAVER
        };
    }
}

@Bean
Step p130Particion(JobRepository repo, Tasklet p130Tasklet, FallaPasoHandler fallas) {
    return new StepBuilder("S500P130", repo)
            .tasklet(p130Tasklet, tx)
            .listener(fallas)                       // ON TASKFAULT -> FALLAPCOPIA
            .allowStartIfComplete(false)
            // ON RESTART: el WFL no hace nada (GO PASO130 comentado).
            // En Java el reinicio de un step FAILED lo vuelve a ejecutar; P130 es
            // actualizador, por lo que la tasklet debe ser idempotente o reanudar por checkpoint.
            .build();
}

