@Component
@RequiredArgsConstructor
public class CierreLoteListener implements JobExecutionListener {

    private final IncidenteNotifier incidentes;     // AVISOINC
    private final P106Service p106;

    @Override
    public void afterJob(JobExecution job) {
        var ctx = job.getExecutionContext();
        int idFalla = ctx.getInt("idFallaPaso", 0);
        List<Integer> fallasP130 = List.of(ctx.getInt("fallaC1", 0),
                                           ctx.getInt("fallaC2", 0), ctx.getInt("fallaC3", 0));

        if (idFalla > 0 || fallasP130.stream().anyMatch(f -> f > 0)) {
            p106.registraIncidenteBatch(ctx.get("fechaBatch", LocalDate.class));  // SUB106
        }
        if (idFalla > 0) incidentes.avisa(idFalla, null);
        int idP106 = ctx.getInt("idFallaP106", 0);
        if (idP106 > 0) incidentes.avisa(idP106, null);
        for (int copia = 1; copia <= 3; copia++) {
            int f = fallasP130.get(copia - 1);
            if (f > 0) incidentes.avisa(f, "/" + copia);    // COP130
        }
        // REMOVE S500/FILE/CTRLWFL/= : no aplica, el JobRepository conserva la historia.
    }
}

/** AVISOINC: CASE IDFALLAPASO OF. Catálogo cerrado de causas de incidente. */
public enum IncidenteLote {
    P106_AVISO_CANCELADOS_S016(50, "ERR AVISO CANCELADOS AL S016"),
    P106_LIGA_S016_L458(51,        "NO SE PUDO LIGAR LIB S016 L458"),
    P130_CALL_CAT279(60,           "ERR CALL CATALOGO 279"),
    P130_LLAVE_CAT279(61,          "ERR LLAVE INTERNA CAT-279"),
    P130_VALOR_CAT279(62,          "ERR VALOR EN CATALOGO 279"),
    P130_SIN_CETES_DIA(63,         "NO EXISTE TARIFA CETES DEL DIA EN S080"),
    P130_SIN_TARIFA_DIA(64,        "NO EXISTE TARIFA DIA EN S080"),
    P130_SIN_CETES_PROM(65,        "NO EXISTE TARIFA CETES PROMEDIO EN S080"),
    P130_SIN_TARIFA_PROM(66,       "NO EXISTE TARIFA PROM EN S080"),
    P130_SUC_PROMOTORA(67,         "CAMBIO DE SUC/PROMOTORA INVALIDO"),
    P130_GBNP_TASA_ANTERIOR(68,    "GBNP SE PAGO CON UNA TASA ANT"),
    P130_NOTLOCKED(69,             "NOTLOCKED SIN AFECTACION"),
    DESCONOCIDO(-1,                "ERROR DESCONOCIDO");
    // ... códigos 70-83 (P105), 90 (P186) y 99 (P160, P170, P110)

    private final int codigo; private final String texto;
    IncidenteLote(int codigo, String texto) { this.codigo = codigo; this.texto = texto; }

    public static IncidenteLote de(int codigo) {
        return Arrays.stream(values()).filter(i -> i.codigo == codigo)
                     .findFirst().orElse(DESCONOCIDO);
    }
}
